const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bill:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Z"/><path d="M9 8h6m-6 4h6"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M16 10h5v6h-5a3 3 0 0 1 0-6ZM4 5l12-3v3"/>',coffee:'<path d="M4 9h12v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V9Zm12 1h2a3 3 0 0 1 0 6h-2M7 3v3m5-3v3"/>',bag:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',home:'<path d="m3 10 9-7 9 7v10H3V10Zm6 10v-7h6v7"/>',link:'<path d="m9 15 6-6m-7 4-2 2a4 4 0 0 0 6 6l3-3m1-7 2-2a4 4 0 0 0-6-6L9 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4l-2 4Zm5 3h4"/>',store:'<path d="M3 9h18l-3-6H6L3 9Zm1 0v12h16V9M9 21v-8h6v8"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.bill}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>(n/100).toFixed(2);let filter='all';let selectedPerson=2;let splitMode='equal';
let bills=[{id:'sunday',name:'Sunday brunch',merchant:'The Morning Table',total:8400,icon:'coffee',color:'',people:['Ayesha','Rafi','You','Nadia'],payments:[2100,2100,0,0],status:'active',refunded:false,items:[['Breakfast plates × 4',6400],['Coffee × 4',1600],['Service charge',400]]},{id:'weekend',name:'Weekend getaway',merchant:'The Lakehouse',total:24000,icon:'home',color:'violet',people:['Rafi','You','Nadia'],payments:[8000,0,0],status:'active',refunded:false,items:[['Weekend reservation',24000]]},{id:'studio',name:'A little studio upgrade',merchant:'Form & Function',total:12600,icon:'bag',color:'blue',people:['Ayesha','Rafi','You'],payments:[4200,4200,4200],status:'paid',refunded:false,items:[['Studio accessories',12600]]},{id:'picnic',name:'Friday picnic',merchant:'Garden Kitchen',total:6000,icon:'coffee',color:'',people:['Ayesha','You','Rafi'],payments:[2000,2000,0],status:'expired',refunded:false,items:[['Picnic basket',6000]]}];
let events=[{name:'Rafi paid their share',detail:'Sunday brunch · Demo activity',amount:2100},{name:'Ayesha paid their share',detail:'Sunday brunch · Demo activity',amount:2100},{name:'Studio checkout completed',detail:'Form & Function · Demo settlement',amount:12600}];
const collected=b=>b.payments.reduce((a,c)=>a+c,0);const statusLabel=b=>b.status==='paid'?'Completed':b.status==='expired'?(b.refunded?'Refunded':'Expired'):'Collecting';
const button=(text,action,style='',ic='')=>`<button class="btn ${style}" ${action}>${ic?icon(ic):''}${text}</button>`;
function shell(content,active='dashboard'){const nav=[['dashboard','grid','Overview'],['checkouts','bill','Checkouts'],['refunds','shield','Claims & refunds'],['merchant','store','Merchant view']];document.getElementById('app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-mark">t</span>treat<span style="color:#abc76f">.</span></a><div class="workspace"><span class="avatar square">A</span><div>Ayesha's space<br><span class="small muted" style="font-size:12px">Personal workspace</span></div><span class="muted" style="margin-left:auto">⌄</span></div><div class="nav-label">WORKSPACE</div><nav class="nav">${nav.map(([id,ic,t])=>`<a href="#${id}" class="${active===id?'active':''}">${icon(ic)}${t}${id==='checkouts'?`<span class="count">${bills.filter(b=>b.status==='active').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help"><span class="icon" style="display:block">${icon('people')}</span><strong>Better with your people.</strong><p class="muted small">One shared bill. A little less back-and-forth.</p><button onclick="showAbout()">Meet Treat ↗</button></div><div class="profile"><span class="avatar" style="background:#eee4d7">AR</span><div class="small">Ayesha Rahman<br><span class="muted" style="font-size:12px">Demo workspace</span></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span style="margin:0 12px">/</span> <strong>${nav.find(n=>n[0]===active)?.[2]||'Checkout'}</strong></div><a class="brand mobile-brand" href="#dashboard"><span class="brand-mark">t</span>treat.</a><div class="top-actions"><span class="demo-label"><i></i> Interactive demo</span><button class="round" aria-label="View recent activity" onclick="location.hash='activity'">${icon('bell')}</button><span class="avatar" style="width:30px;height:30px;background:#e9e2d8">AR</span></div></header><nav class="mobile-nav">${nav.map(([id,ic,t])=>`<a href="#${id}" class="${active===id?'active':''}">${t}</a>`).join('')}</nav><div class="content">${content}<footer class="footer"><span>© ${new Date().getFullYear()} Treat · A little better, together.</span><span>Demo only · No real money moves</span></footer></div></main></div>`;}
function card(b){let amt=collected(b);return `<a class="checkout-card" href="#checkout/${b.id}"><div class="card-top"><div class="merchant-icon ${b.color}">${icon(b.icon)}</div><span class="badge ${b.status}">${statusLabel(b)}</span></div><h3>${esc(b.name)}</h3><div class="card-sub">${esc(b.merchant)}</div><div class="card-amount">${money(amt)} <span>/ ${money(b.total)} USDC</span></div><div class="progress"><div style="width:${amt/b.total*100}%"></div></div><div class="card-meta"><span>${b.payments.filter(n=>n>0).length} of ${b.people.length} contributed</span><span>${Math.round(amt/b.total*100)}%</span></div><div class="card-bottom"><div class="avatars">${b.people.slice(0,4).map(p=>`<span class="avatar">${esc(p[0])}</span>`).join('')}</div><span class="small muted">${b.status==='active'?'View checkout ↗':b.status==='paid'?'View receipt ↗':'View refund ↗'}</span></div></a>`;}
function activity(){return events.slice(0,5).map(e=>`<div class="activity-row"><span class="avatar">${icon('check')}</span><div>${esc(e.name)}<small>${esc(e.detail)}</small></div><strong>${money(e.amount)} <span class="muted">USDC</span></strong></div>`).join('');}
function dashboard(checkoutsOnly=false){let active=bills.filter(b=>b.status==='active');const list=filter==='all'?bills:bills.filter(b=>b.status===(filter==='completed'?'paid':filter));shell(`<div class="page-heading"><div><h1>${checkoutsOnly?'Your checkouts':'Good things happen together.'}</h1><p>${checkoutsOnly?'Every shared bill, from first contribution to final receipt.':'Your shared moments. Your money, in sync.'}</p></div>${button('New checkout','onclick="createModal()"','primary','plus')}</div>${!checkoutsOnly?`<section class="hero"><div class="hero-copy"><div class="eyebrow">LESS CHASING. MORE LIVING.</div><h2>You bring the people.<br>We bring it together.</h2><p>Split the bill, treat a friend, and settle together.<br>One checkout. Everyone's share.</p>${button('Try group checkout',`onclick="location.hash='checkout/sunday'"`,'lime','arrow')}</div><div class="hero-art" aria-label="Example group checkout"><div class="mini-checkout"><div class="mini-line"><strong>The Morning Table</strong>${icon('coffee').replace('<svg','<svg width="17" height="17"')}</div><div class="small muted">Sunday, well spent.</div><div class="money">84.00 <span class="unit">USDC</span></div><div class="avatars"><span class="avatar">A</span><span class="avatar">R</span><span class="avatar">Y</span><span class="avatar">N</span></div><div class="progress"><div style="width:50%"></div></div><div class="mini-line"><span>2 of 4 contributed</span><strong>Halfway there</strong></div></div><div class="float-pill">✓ A little treat, on you.</div></div></section><section class="stats"><div class="stat"><div class="stat-head">Total collected ${icon('wallet')}</div><div class="money">${money(bills.filter(b=>!b.refunded).reduce((s,b)=>s+collected(b),0))} <span class="unit">USDC</span></div><div class="stat-foot"><strong>Across ${bills.length} checkouts</strong> · Demo workspace</div></div><div class="stat"><div class="stat-head">Active checkouts ${icon('bill')}</div><div class="money">${String(active.length).padStart(2,'0')}</div><div class="stat-foot">A few good things coming together</div></div><div class="stat"><div class="stat-head">Waiting to be covered ${icon('clock')}</div><div class="money">${money(active.reduce((s,b)=>s+b.total-collected(b),0))} <span class="unit">USDC</span></div><div class="stat-foot">Remaining across active checkouts</div></div></section>`:''}<section><div class="section-head"><h2>${checkoutsOnly?'All checkouts':'Your checkouts'}<span class="heading-count">${bills.length}</span></h2>${!checkoutsOnly?'<a class="small muted" href="#checkouts">View all ↗</a>':''}</div><div class="tabs" role="group" aria-label="Filter checkouts">${[['active','Active'],['completed','Completed'],['expired','Expired'],['all','All checkouts']].map(([v,t])=>`<button class="${filter===v?'selected':''}" onclick="filter='${v}';dashboard(${checkoutsOnly})">${t}</button>`).join('')}</div><div class="cards">${(checkoutsOnly?list:list.slice(0,3)).map(card).join('')||'<div class="empty">No checkouts here yet.</div>'}</div></section>${!checkoutsOnly?`<div class="lower-grid"><section class="activity-panel"><div class="section-head"><h2>Little updates</h2><a href="#activity" class="small muted">View all ↗</a></div>${activity()}</section><section class="note-panel"><span class="eyebrow">A LITTLE PEACE OF MIND</span><h2>Plans change. That's okay.</h2><p>If a checkout expires before it's fully funded, contributors can claim their money back.</p><a href="#refunds" class="btn text" style="justify-content:flex-start">Explore claims & refunds ${icon('arrow')}</a></section></div>`:''}`,checkoutsOnly?'checkouts':'dashboard');}
function getBill(id){return bills.find(b=>b.id===id)}
function detail(id){const b=getBill(id);if(!b){shell('<div class="empty"><h2>Checkout not found</h2><p>This demo link is unavailable in this session.</p><a class="btn" href="#dashboard">Back to overview</a></div>');return;}if(selectedPerson>=b.people.length)selectedPerson=0;let remaining=b.total-collected(b),share=Math.max(0,Math.floor(b.total/b.people.length)+(selectedPerson===b.people.length-1?b.total%b.people.length:0)-b.payments[selectedPerson]);shell(`<a href="#checkouts" class="back">${icon('back').replace('<svg','<svg width="16" height="16"')} All checkouts</a><div class="page-heading"><div><h1>${esc(b.name)}</h1><p>One bill. Your people. Everyone's share.</p></div>${button('Share link',`onclick="shareBill('${b.id}')"`,'','link')}</div><div class="checkout-layout"><section class="panel"><div class="bill-header"><div><div class="eyebrow muted">GROUP CHECKOUT</div><h2>${esc(b.merchant)}</h2><span class="small muted">${esc(b.id.toUpperCase())} · Sample bill</span></div><div class="merchant-icon ${b.color}">${icon(b.icon)}</div></div>${b.items.map(([n,a])=>`<div class="bill-item"><span>${esc(n)}</span><strong>${money(a)} USDC</strong></div>`).join('')}<div class="bill-total"><span>Total bill</span><span>${money(b.total)} USDC</span></div><div class="section-head" style="margin-top:35px"><h2>Your people</h2><span class="badge ${b.status}">${statusLabel(b)}</span></div>${b.people.map((p,i)=>`<div class="people-row"><span class="avatar" style="background:${['#eceddc','#f0e3d9','#e9e5f4','#e4edf0'][i%4]}">${esc(p[0])}</span><div class="name">${esc(p)}${p==='You'?' <span class="muted small">(demo)</span>':''}<div class="small muted" style="font-size:12px;margin-top:3px">${b.payments[i]>0?'Contributed':'Not contributed yet'}</div></div><strong class="small">${money(b.payments[i])} <span class="muted">USDC</span></strong>${b.payments[i]>0?'<span style="color:#7b9e51">✓</span>':''}</div>`).join('')}<div class="notice">${b.status==='paid'?'✓ Demo settlement complete. The merchant has received the full simulated bill amount.':b.status==='expired'?'This checkout has expired. Unsettled contributions are eligible for a demo refund.':'Contributions stay pending until the full bill is covered. If the checkout expires first, contributors can claim a refund.'}</div>${b.status==='active'?button('Preview expiry & refund',`onclick="expireBill('${b.id}')"`,'text','clock'):''}</section><aside class="panel payment-panel"><div class="small muted">${b.status==='paid'?'Paid together':b.status==='expired'?'Collected before expiry':'Still to come together'}</div><div class="money">${money(b.status==='paid'?b.total:b.status==='expired'?collected(b):remaining)} <span class="unit">USDC</span></div><div class="progress"><div style="width:${collected(b)/b.total*100}%"></div></div><div class="card-meta"><span>${money(collected(b))} collected</span><span>${Math.round(collected(b)/b.total*100)}%</span></div>${b.status==='active'?`<h3>Make it your share.</h3><label for="person">Contribute as</label><select id="person" onchange="selectedPerson=Number(this.value);detail('${b.id}')">${b.people.map((p,i)=>`<option value="${i}" ${i===selectedPerson?'selected':''}>${esc(p)}${p==='You'?' · demo participant':''}</option>`).join('')}</select><div class="tabs"><button class="${splitMode==='equal'?'selected':''}" onclick="splitMode='equal';detail('${b.id}')">Equal share</button><button class="${splitMode==='custom'?'selected':''}" onclick="splitMode='custom';detail('${b.id}')">Custom amount</button></div><label for="amount">Your contribution (USDC)</label><input id="amount" type="number" min="0.01" max="${money(remaining)}" step="0.01" value="${money(Math.min(share,remaining))}" ${splitMode==='equal'?'readonly':''}>${button('Simulate contribution',`onclick="pay('${b.id}',selectedPerson,document.getElementById('amount').value)"`,'primary','arrow')}${button('Treat the rest · '+money(remaining),`onclick="pay('${b.id}',selectedPerson,'${money(remaining)}')"`,'','people')}<p class="disclaimer">Interactive demo · No wallet connected.<br>No real USDC or network fees are involved.</p>`:b.status==='paid'?`<div class="notice">✓ All together. All settled.</div>${button('Download demo receipt',`onclick="receipt('${b.id}')"`,'primary','bill')}<p class="disclaimer">This is a simulated receipt, not proof of an on-chain payment.</p>`:`<div class="notice">${b.refunded?'Demo refunds have been issued to the original contributors.':'Refunds return each contribution to its original payer.'}</div>${button(b.refunded?'Refunds completed':'Simulate all refunds',`${b.refunded?'disabled':`onclick="refund('${b.id}')"`}`,'primary','shield')}`}<div style="border-top:1px solid var(--line);padding-top:20px;margin-top:25px;display:flex;gap:10px;align-items:center" class="small muted"><span class="icon">${icon('shield')}</span>Clear amounts. Clear outcomes.</div></aside></div>`,'checkouts');}
function pay(id,person,value){const b=getBill(id),num=Number(value);if(!b||b.status!=='active')return toast('This checkout is no longer collecting.');if(!Number.isInteger(person)||person<0||person>=b.people.length)return toast('Choose a valid participant.');const cents=Math.round(num*100);if(!Number.isFinite(num)||cents<=0||Math.abs(num*100-cents)>0.00001)return toast('Enter an amount with up to two decimal places.');if(cents>b.total-collected(b))return toast('That is more than the remaining bill.');b.payments[person]+=cents;events.unshift({name:`${b.people[person]} contributed`,detail:`${b.name} · Simulated payment`,amount:cents});if(collected(b)===b.total){b.status='paid';toast('Everyone is covered. Demo merchant settlement complete.');}else toast('Demo contribution added. You’re a little closer.');detail(id);return {status:b.status,collected:collected(b),remaining:b.total-collected(b)};}
function expireBill(id){const b=getBill(id);if(!b||b.status!=='active')return;b.status='expired';detail(id);toast('Demo checkout expired. Refunds are now available.');}
function refund(id){let b=getBill(id);if(!b||b.status!=='expired'||b.refunded)return;b.refunded=true;events.unshift({name:'Contributors refunded',detail:`${b.name} · Simulated refund`,amount:collected(b)});route();toast('Demo refunds completed for original contributors.');}
function merchant(){shell(`<div class="page-heading"><div><h1>Your business, together.</h1><p>Create a bill. Share the link. Receive one complete payment.</p></div>${button('Create a bill','onclick="createModal()"','primary','plus')}</div><div class="stats"><div class="stat"><div class="stat-head">Settled in demo ${icon('wallet')}</div><div class="money">${money(bills.filter(b=>b.status==='paid').reduce((s,b)=>s+b.total,0))} <span class="unit">USDC</span></div><div class="stat-foot">Completed checkouts only</div></div><div class="stat"><div class="stat-head">Open bills ${icon('bill')}</div><div class="money">${bills.filter(b=>b.status==='active').length}</div><div class="stat-foot">Awaiting group contributions</div></div><div class="stat"><div class="stat-head">Completed bills ${icon('check')}</div><div class="money">${bills.filter(b=>b.status==='paid').length}</div><div class="stat-foot">Full amount covered</div></div></div><section class="panel"><div class="section-head"><h2>Payment overview</h2><span class="demo-label">Demo ledger</span></div><div class="table-wrap"><table><thead><tr><th>BILL / MERCHANT</th><th>AMOUNT</th><th>COLLECTED</th><th>STATUS</th><th></th></tr></thead><tbody>${bills.map(b=>`<tr><td><strong>${esc(b.name)}</strong><div class="muted small" style="margin-top:4px;font-size:12px">${esc(b.merchant)}</div></td><td>${money(b.total)} USDC</td><td>${money(collected(b))}</td><td><span class="badge ${b.status}">${statusLabel(b)}</span></td><td><a class="btn" href="#checkout/${b.id}">Open ↗</a></td></tr>`).join('')}</tbody></table></div></section>`,'merchant');}
function refunds(){shell(`<div class="page-heading"><div><h1>Back where it belongs.</h1><p>Claims & refunds for checkouts that didn't come together.</p></div></div><div class="notice">Demo refunds return the full contributed amount to each original participant. Real payment integration is not enabled.</div><div class="cards">${bills.filter(b=>b.status==='expired').map(card).join('')||'<div class="empty">No refunds to claim. You’re all caught up.</div>'}</div>`,'refunds');}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function modal(html){const el=document.getElementById('modal');el.innerHTML=html;el.showModal();}function closeModal(){document.getElementById('modal').close();}
function createModal(){modal(`<div class="modal-title"><h2>A new thing, together.</h2><button class="round" aria-label="Close dialog" onclick="closeModal()">${icon('close')}</button></div><form id="create-form"><label for="bill-name">What's the occasion?</label><input id="bill-name" name="name" required maxlength="60" placeholder="e.g. Friday dinner"><label for="merchant-name">Merchant name</label><input id="merchant-name" name="merchant" required maxlength="60" placeholder="e.g. The Morning Table"><label for="bill-total">Total bill (USDC)</label><input id="bill-total" name="amount" type="number" min="0.01" max="100000" step="0.01" placeholder="60.00" required><label for="bill-people">People sharing · 2–12</label><input id="bill-people" name="people" type="number" min="2" max="12" step="1" value="3" required><div class="notice">Creates a temporary checkout in this demo session. Refreshing resets the workspace.</div><button class="btn primary" type="submit">Create demo checkout ${icon('arrow')}</button></form>`);document.getElementById('create-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),num=Number(f.get('amount')),n=Number(f.get('people'));if(!Number.isFinite(num)||num<=0||num>100000||!Number.isInteger(n)||n<2||n>12)return;let id='bill-'+Date.now().toString(36);bills.unshift({id,name:String(f.get('name')).trim(),merchant:String(f.get('merchant')).trim(),total:Math.round(num*100),icon:'bill',color:'blue',people:Array.from({length:n},(_,i)=>i===0?'You':'Friend '+i),payments:Array(n).fill(0),status:'active',refunded:false,items:[['Shared bill',Math.round(num*100)]]});selectedPerson=0;closeModal();location.hash='checkout/'+id;toast('Your demo checkout is ready.');};}
async function shareBill(id){const url=location.href.split('#')[0]+'#checkout/'+id;modal(`<div class="modal-title"><h2>Bring everyone together.</h2><button class="round" aria-label="Close dialog" onclick="closeModal()">${icon('close')}</button></div><p class="small muted" style="line-height:1.7">Demo link only. Sample checkouts open on other devices, but contributions do not sync. Custom checkouts exist in this session only.</p><label for="share-url" style="margin-top:20px">Checkout link</label><input id="share-url" readonly value="${esc(url)}">${button('Copy demo link','onclick="copyLink()"','primary','link')}`);}
async function copyLink(){const input=document.getElementById('share-url');try{await navigator.clipboard.writeText(input.value);toast('Demo link copied.');}catch{input.select();toast('Select and copy the link above.');}}
function receipt(id){let b=getBill(id);if(!b||b.status!=='paid')return;const txt=`TREAT — DEMO RECEIPT\nNot an on-chain payment receipt.\n\n${b.name}\nMerchant: ${b.merchant}\nTotal: ${money(b.total)} USDC\nStatus: Simulated settlement complete\n\n${b.people.map((p,i)=>p+': '+money(b.payments[i])+' USDC').join('\n')}`;const url=URL.createObjectURL(new Blob([txt],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=`treat-${b.id}-demo-receipt.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showAbout(){modal(`<div class="modal-title"><h2>A little better, together.</h2><button class="round" aria-label="Close dialog" onclick="closeModal()">${icon('close')}</button></div><p class="intro-copy">Treat brings everyone’s share into one checkout. Choose a sample bill, simulate a contribution, cover the remainder, or explore what happens when a checkout expires.</p><div class="notice">This prototype uses temporary demo data. Wallets, real payments, QR generation, shared persistence, and Arc settlement are not connected yet.</div>${button('Try the brunch checkout',`onclick="closeModal();location.hash='checkout/sunday'"`,'primary','arrow')}`);}
function route(){const hash=location.hash.slice(1)||'dashboard';if(hash.startsWith('checkout/'))detail(hash.slice(9));else if(hash==='merchant')merchant();else if(hash==='refunds')refunds();else if(hash==='activity')shell(`<div class="page-heading"><div><h1>Every little update.</h1><p>Your demo contributions, settlements, and refunds.</p></div></div><section class="activity-panel">${activity()}</section>`);else dashboard(hash==='checkouts');window.scrollTo(0,0);}
document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_demo_checkouts',description:'Read the current session’s simulated Treat checkouts. No real payment data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({checkouts:bills.map(b=>({id:b.id,name:b.name,totalCents:b.total,collectedCents:collected(b),status:b.status}))})});document.modelContext.registerTool({name:'open_demo_checkout',description:'Navigate to an existing demo checkout. Does not contribute or transfer money.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},execute:input=>{if(!input||typeof input.id!=='string'||!getBill(input.id))throw new Error('Unknown demo checkout');location.hash='checkout/'+input.id;detail(input.id);return{id:input.id,opened:true};}});}catch(e){console.warn('Optional page tools unavailable',e);}}

